    'POSIBLE SOLUCIÓN (hipótesis): ' + (h.offer || '—'),
    '',
    'EVIDENCIA  (✔ cita literal verificada en la URL · ~ inferencia · ? no verificada):',
  ].concat(ev, [
    '',
    'CONTACTO PÚBLICO (' + channel + '): ' + person + ' · ' + contactLine + ' · fuente ' + (c.source_url || '—'),
    'Puntos por factor: ' + factorLine,
